class AccountService:
    def __init__(self) -> None:
        # email (lowercased) -> {"password": str, "is_admin": bool, "display_name": str}
        self._accounts: dict[str, dict] = {}
        # token -> email (lowercased)
        self._reset_tokens: dict[str, str] = {}

