        requester = self._accounts.get(requester_email.lower())
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets.")
        target_key = target_email.lower()
        if target_key not in self._accounts:
            raise ValueError("No account exists for the target email.")
        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_key
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        email = self._reset_tokens.pop(token, None)
        if email is None:
            raise ValueError("Invalid or already-used reset token.")
        self._accounts[email]["password"] = new_password

    def list_users(self) -> list[str]:
        return sorted(self._accounts.keys())

    def display_name(self, email: str) -> str:
        account = self._accounts.get(email.lower())
        if account is None:
            raise ValueError("No account exists for this email.")
        return account["display_name"]
